import{_ as t,c as e,o as a,a4 as r}from"./chunks/framework.DzOtv0XR.js";const u=JSON.parse('{"title":"SSR","description":"","frontmatter":{},"headers":[],"relativePath":"project/ssr.md","filePath":"project/ssr.md"}'),l={name:"project/ssr.md"},i=r('<h2 id="why" tabindex="-1">why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;why&quot;">​</a></h2><p>SPA 客户端渲染依赖框架（vue/router/vuex），需要等框架加载完</p><h2 id="what" tabindex="-1">what <a class="header-anchor" href="#what" aria-label="Permalink to &quot;what&quot;">​</a></h2><table><thead><tr><th>简称</th><th>类型</th><th>优点</th><th style="text-align:left;">缺点</th><th>适用场景</th></tr></thead><tbody><tr><td>CSR</td><td>纯 JS 渲染</td><td>易于跨终端</td><td style="text-align:left;">首屏渲染慢，SEO不友好</td><td>不需要登录</td></tr><tr><td>SSR</td><td>服务端渲染（即时，返回动态 HTML)</td><td>改善所有指标</td><td style="text-align:left;">需要服务器即时处理，增加开发调试成本（服务器渲染交互</td><td>SEO、首屏有强需求</td></tr><tr><td>SSG</td><td>服务端预渲染(返回静态 HTML)</td><td>静态服务器即可</td><td style="text-align:left;"></td><td>只适合静态内容</td></tr><tr><td>ISG</td><td>服务端增量生成</td><td>解决 SSG 问题</td><td style="text-align:left;">带来其他问题，如问题定位和缓存</td><td></td></tr></tbody></table><p><img src="https://img.oaker.bid/?url=http://tvax1.sinaimg.cn/large/4e5d3ea7gy1h9plzy33baj21c00r8qsc.jpg" alt="Pasted image 20221228093741.png"></p><p><img src="https://img.oaker.bid/?url=http://tvax1.sinaimg.cn/large/4e5d3ea7gy1h9pm0f6relj20og0b8wlf.jpg" alt="Pasted image 20221227094939.png"><img src="https://img.oaker.bid/?url=http://tvax1.sinaimg.cn/large/4e5d3ea7gy1h9pm102k1gj23js298npd.jpg" alt="Pasted image 20221227095117.png"></p><h1 id="ssr" tabindex="-1">SSR <a class="header-anchor" href="#ssr" aria-label="Permalink to &quot;SSR&quot;">​</a></h1><p><a href="https://cn.vuejs.org/guide/scaling-up/ssr.html#why-ssr" target="_blank" rel="noreferrer">服务端渲染 (SSR) | Vue.js</a></p><p><a href="https://juejin.im/post/5bbda9ed5188255c8f06c0dc" target="_blank" rel="noreferrer">带你五步学会Vue SSR - 掘金</a></p><p>SSR 的 HTML</p><ol><li>更快（尤其是当您的JS与广告/分析等竞争时）</li><li>更易于抓取和归档</li><li>对可能导致JS失败的许多情况（有缺陷的连接，配置错误的公共wifi，adblocker）具有弹性</li></ol><p>同构（通用）</p><ul><li>首屏白屏问题，客户端只负责解析 HTML</li><li>SEO 问题</li></ul><p>权衡：</p><ol><li>开发限制，如特殊勾子，外部库需要特殊处理</li><li>部署要求，app server vs static server</li><li>服务端负载，更占用 CPU，高流量需要考虑合理的缓存</li></ol><p>挑战：</p><ol><li>两次构建</li><li>保证正确的资源链接和提示</li><li>以通用的方式管理路由、数据获取和状态存储</li></ol><p>对于同构应用来说，我们必须实现客户端与服务端的路由、模型组件、数据模型的共享。</p><p>后续访问用客户端渲染</p><h2 id="ssr-对性能优化的提升在哪里" tabindex="-1">SSR 对性能优化的提升在哪里 <a class="header-anchor" href="#ssr-对性能优化的提升在哪里" aria-label="Permalink to &quot;SSR 对性能优化的提升在哪里&quot;">​</a></h2><p>预渲染，提升首屏</p><p><a href="https://www.zhihu.com/question/308792091/answer/575636896" target="_blank" rel="noreferrer">有必要使用服务器端渲染(SSR)吗？ - 知乎</a></p><p><a href="https://note.youdao.com/ynoteshare1/index.html?id=9174b59418d987cd810dc058a7b6a121&amp;type=note" target="_blank" rel="noreferrer">官网预渲染方案-有道云笔记</a></p><h2 id="ssg-预渲染" tabindex="-1">SSG（预渲染） <a class="header-anchor" href="#ssg-预渲染" aria-label="Permalink to &quot;SSG（预渲染）&quot;">​</a></h2><p>好处：</p><ol><li>与 SSR 同等的首屏性能</li><li>更容易部署，低负载</li></ol><p>限制</p><ol><li>静态数据</li></ol><p>场景：</p><ol><li>营销页面</li><li>官网、博客</li></ol><p>SSR 实时请求、渲染、响应，IDC</p><p>SSG 可以放在 CDN，构建时即确定渲染</p><p><a href="https://www.xuanbiyijue.com/2021/08/17/%E9%A2%84%E6%B8%B2%E6%9F%93%E3%80%81SSR%E3%80%81SSG%E3%80%81ISR/" target="_blank" rel="noreferrer">预渲染、SSR、SSG、ISR | 悬笔e绝的个人博客</a></p><p><a href="https://reactjs.org/blog/2022/03/29/react-v18.html#gradually-adopting-concurrent-features" target="_blank" rel="noreferrer">React v18.0 – React Blog</a></p><p>最佳实践是结合</p><h2 id="issues" tabindex="-1">issues <a class="header-anchor" href="#issues" aria-label="Permalink to &quot;issues&quot;">​</a></h2><p><a href="https://www.v2ex.com/t/845794" target="_blank" rel="noreferrer">Vue 3 的服务端与异步数据获取 - V2EX</a></p><h2 id="结合业务" tabindex="-1">结合业务 <a class="header-anchor" href="#结合业务" aria-label="Permalink to &quot;结合业务&quot;">​</a></h2><p>有框架依赖，复杂应用，大公司首选</p>',39),s=[i];function d(o,p,h,n,c,S){return a(),e("div",null,s)}const f=t(l,[["render",d]]);export{u as __pageData,f as default};
